<?php $rotulos=['recebido'=>'Recebido','em_preparacao'=>'Em preparação','enviado'=>'Enviado','concluido'=>'Concluído','cancelado'=>'Cancelado']; ?>
<section class="panel"><div class="panel-header"><div><p class="eyebrow">Pedido #<?= (int)$pedido['id'] ?></p><h2><?= e($pedido['nome_cliente']) ?></h2><p><?= e($pedido['email_cliente']) ?> · <?= e(date('d/m/Y H:i',strtotime($pedido['created_at']))) ?></p></div><span class="badge badge-info"><?= e($rotulos[$pedido['status']]??$pedido['status']) ?></span></div><div class="table-wrap"><table><thead><tr><th>Jogo</th><th>Preço unitário</th><th>Quantidade</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($pedido['itens'] as $item): ?><tr><td class="text-left"><?= e($item['titulo_jogo']) ?></td><td>R$ <?= number_format((float)$item['preco_unitario'],2,',','.') ?></td><td><?= (int)$item['quantidade'] ?></td><td>R$ <?= number_format((float)$item['subtotal'],2,',','.') ?></td></tr><?php endforeach; ?></tbody></table></div><div class="checkout-grand-total"><span>Total</span><strong>R$ <?= number_format((float)$pedido['total'],2,',','.') ?></strong></div><p><strong>Entrega:</strong> <?= e($pedido['nome_destinatario']) ?> · <?= e($pedido['endereco']) ?> · <?= e($pedido['cidade']) ?> · CEP <?= e($pedido['cep']) ?></p><p><strong>Pagamento:</strong> <?= e(strtoupper($pedido['forma_pagamento'])) ?></p>
<?php if ($pedido['status']!=='cancelado'): ?><form method="post" action="index.php?entidade=pedidos&acao=atualizar" class="filters"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$pedido['id'] ?>"><div class="field"><label for="status">Atualizar status</label><select id="status" name="status"><?php $opts=['recebido'=>['recebido','em_preparacao','cancelado'],'em_preparacao'=>['em_preparacao','enviado','cancelado'],'enviado'=>['enviado','concluido'],'concluido'=>['concluido']]; foreach (($opts[$pedido['status']]??[]) as $s): ?><option value="<?= $s ?>"><?= e($rotulos[$s]) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Atualizar pedido</button></form><?php else: ?><form method="post" action="index.php?entidade=pedidos&acao=excluir" onsubmit="return confirm('Excluir permanentemente este pedido cancelado?')"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$pedido['id'] ?>"><button class="btn btn-secondary">Excluir pedido cancelado</button></form><?php endif; ?><p><a class="btn btn-secondary" href="index.php?entidade=pedidos">Voltar aos pedidos</a></p></section>
